INSERT INTO teas (name, slug, phonetic_name, original_name, description, origin, tea_type, category, caffeine_level, brewing_temp_c, brewing_time_min, brewing_num_brews, brewing_instructions, characteristics, health_benefits, color_hex, oxidation_level, roast_level, flavor_x, flavor_y, source_type, source, owner_id, is_public) VALUES
('Sum-cha', 'breathing-tea-fermented-herbs', '', '숨차', 'Breathing tea is an herbal tea developed by Mr Chou in South Korea. Breathing tea consists of herbs that have undergone a fermentation process for 35 days. In this series there are 5 types (Light, Goodnight, Willowy and Relief tea) and they complement each other well. 1 tea bag can be used 3 times (3 cups) or for 1 litre of tea. The tea tastes very mild and is equally good cold or hot. 10 teabags in a bag. Net weight per teabag 1.2g Ingredienser: lilla klokkeblomst (60 %),orientalsk gedeskæg (40 %).', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Herbal','Caffeine-Free']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Da Hong Pao', 'dahongpao-zhengyan-yancha', '', '大红袍', 'Grown in the core part - Zhengyan - of Wuyishan park, these leaves come from the Qidan cultivar that derived from one of the six "Mother Tree" shrubs of Dahongpao (see photo), which gives it an intense flavour and an inebriating floral aroma, accompanied by a pleasant roasted fragrance that is revealed at the first infusion, and then leaves space for the botanical notes and minerality typical of rock teas born in the center of Wuyishan natural park. Dried with a high charcoal-roasting , this tea welcomes in a harmonious and balanced way all the sensorial aspects that make rock teas unique: roasted notes opening the senses to the floral and mineral notes described in the saying 岩骨花香 Yan Gu...', '', 'oolong', 'true_tea', 'medium', 90, 3, 3, 'Use 5g per 100ml at 90–95°C. Quick rinse, then 45–90 seconds per infusion; 5+ infusions.', ARRAY['Floral','Creamy']::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE),
('Darjeeling 1st flush 2026, Maharani Hills', 'darjeeling-1st-flush-2026-maharani-hills', '', '', 'Darjeeling tea comes from the North Indian province of Darjeeling, which is located at the foot of the Himalayas. Here the bushes grow at an altitude of up to 2000 m and are called the “champagne of teas”. Maharani Hills produces an outstanding quality with greenish-tippy first flush leaves at over 2,000 meters. A sweet floral aroma, slightly fruity and with a balanced astringency. Flavour: soft with a fresh and flowery character Ingredienser: sort te. Preparation Darjeeling 1st flush is brewed in a preheated pot. The water must not boil for a long time, as this will boil the oxygen out of the water. Use 1 tsp. tea per cup. Pour 90-95 degrees hot water over the leaves. Steeping time: 3 – ...', '', 'black', 'true_tea', 'medium', 95, 3, 3, 'Use 3g per 200ml at 90–95°C. Steep 3–4 minutes.', ARRAY['Bold','Malty']::text[], '{}'::text[], '#8B4513', 90, 70, 78, 55, 'default', 'Teapp', NULL, TRUE),
('Earl Grey With Natural Bergamot', 'earl-grey-with-natural-bergamot', '', '', 'This Earl Grey has the coveted sweet-sour flavour from the citrus fruit bergamot. It is a quality tea where the aroma is a natural bergamot aroma. Our Earl Grey is very popular as there are versions of Earl Grey on the market, but this one has achieved top results when we have done tastings. A classic for a reason, Earl Grey is a rich and sweet tea, no tea cabinet is complete without it. Earl Grey is named after Earl Charles Grey, who was Prime Minister under King William IV in the early 19th century. Legend has it that the earl was given the recipe by a Chinese mandarin who was his friend and whose life he had saved. Ingredienser: sort te, bergamote oil', '', 'blend', 'blend', 'medium', 95, 4, 3, 'Use 3g per 200ml at 95°C. Steep 3–4 minutes.', ARRAY['Citrusy','Bold']::text[], '{}'::text[], '#B07D56', 40, 30, 50, 40, 'default', 'Teapp', NULL, TRUE),
('Fukamushi Kabusecha', 'fukamushi-kabusecha-shade-grown-slow-steamed', '', '深蒸しかぶせ茶', 'Fukamushi is a category and can be translated as "long-steamed". This means that this tea is steamed 2-3 times longer than, for example, a regular sencha, which produces a more rounded taste. Kabusecha is a tea that has grown in the shade for approximately a week before picking. This gives the tea a sweeter and more nuanced taste. Fukamushi Kabusecha is therefore a "long-steamed shadow tea". Japanese green tea can be enjoyed cold as well as hot, as these teas have a mild and fresh taste. You can also brew the cold tea in cold water, but the leaves just have to steep for a longer time. This tea is from our producer Hoshino Seichaen in Yame, Fukuoka, Japan. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Genmaicha with Matcha', 'genmaicha-with-matcha', '', '抹茶入り玄米茶', 'Genmaicha is a blend of Japanese sencha and brown rice. The aroma from the brown rice mixes with the fresh taste and umami from sencha, making it a recommended drink for any occasion, both with food or when you want to take a break. The tea is brewed at approximately 80 degrees and the tea can be enjoyed hot or cold. From Horii Shichimeien you get a classic Japanese everyday tea in the luxury class. Horii Shichimeien, founded in 1879, still manage the 600-year-old Okunuoyama Tea Garden in Uji, Kyoto. This garden is the only survivor of 7 historic tea gardens in Kyoto. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Nutty','Toasty']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Saga no Yuki Genmaicha', 'genmaicha-with-roasted-brown-rice-saga-no-yuki', '', '佐賀の雪玄米茶', 'Genmaicha is the Japanese name for a green tea with roasted rice grains. In this Genmaicha, there is roasted brown rice, which gives a nice nutty aftertaste. It is a very popular tea in Japan and a classic tea to enjoy with food. In addition, Genmaicha is extremely suitable for drinking cold. This tea is the producer Hoshino Seichaen in Yame, Fukuoka, Japan. Ingredienser: grøn te, ristet brun ris', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Nutty','Toasty']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Joseuk-cha', 'good-night-tea-fermented-herbs', '', '조숙차', 'Goodnight tea is an herbal tea developed by Mr Chou in South Korea. Goodnight tea consists of herbs that have undergone a fermentation process for 35 days. There are 5 types in this series (Light, Breathing, Willowy, Relief) and they complement each other well. 1 tea bag can be used 2-3 times (3 cups) or for 1 litre of tea. The tea tastes mild but deep and is equally good cold or hot. 10 teabags in a bag. Net weight per teabag 1.2g Ingredienser: Jeju bambusblade (30 %), Dan-shen rod (40 %), lotusblade (30 %).', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Herbal','Caffeine-Free']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Green Sencha With Apple And Quince', 'green-sencha-with-apple-and-quince', '', '', 'This Sencha with added apple and quince is a popular blend that can be enjoyed at any time of the day. Brewed at 80 degrees, the combination of large-leafed Chinese sencha and fruits produce a spicy yet sweet green tea. Ingredienser: grøn te, æble, naturlig kvædearoma.', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Green Tea With Ginger And Citrus Flavour', 'green-tea-with-ginger-and-citrus-flavour', '', '', 'Green tea with ginger and citrus flavour has a mild and refreshing taste of citrus and spicy aromas. Bergamotte, a citrus fruit known for its fragrant peel, adds a subtle floral and aromatic note to the blend. The tea can be enjoyed hot or cold. Add a drop of honey to the hot tea before cooling it down to iced tea. Ingredienser: Grøn te (75,5 %), ingefær (20 %), naturlig aroma (citron, 3,75 %), bergamot (0,75 %).', '', 'blend', 'blend', 'medium', 95, 4, 3, 'Use 3g per 200ml at 95°C. Steep 3–4 minutes.', ARRAY['Aromatic','Citrusy']::text[], '{}'::text[], '#B07D56', 40, 30, 50, 40, 'default', 'Teapp', NULL, TRUE),
('Gyokuro "Classic" - Edible Leaves', 'gyokuro-classic-edible-leaves', '', '玉露', 'Making the tea leaves for gyokuro is a very demanding process that requires great knowledge. The bushes are covered with rice straw mats 20 days before they are to be harvested and thereby develop a deep green leaf which gives a soft characteristic taste. Gyokuro means "pearl fog" and is among the finest of the Japanese teas. At Sing Tehus, we can offer several different Gyokuro teas, all of which are grown and produced according to the requirements that apply in Japan if you want to sell a tea under the name Gyokuro. Good Gyokuro has a deep and mellow taste also known as Umami. The nuances of taste will vary from product to product as different tea cultivars can be used for production. I...', '', 'green', 'true_tea', 'medium', 60, 2, 3, 'Use 4g per 100ml at 50–60°C. Steep 90–120 seconds; re-steep 2–3 times, raising temperature slightly.', ARRAY['Umami','Sweet']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Oku no Tsuyu', 'gyokuro-oku-no-tsuyu', '', '奥の露', 'This is a g yokuro grown in covered tea fields has a unique aroma called "mukimiko". It has a rich flavor similar to dashi stock. It is delicious when brewed slowly at low temperature or in water. Recommended for tea lovers and those who want to fully enjoy Uji Gyokuro. When brewing Gyokuro Oku no Tsuyu, it is recommended to use water at lower temperatures (around 50 degrees Celsius) to highlight the subtle nuances of the taste. Founded in 1879, Horii Shichimeien continues to cultivate the renowned 600-year-old Okunoyama Tea Garden, the sole remaining tea garden of Kyoto’s historic “seven beautiful gardens”. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 60, 2, 3, 'Use 4g per 100ml at 50–60°C. Steep 90–120 seconds; re-steep 2–3 times, raising temperature slightly.', ARRAY['Umami','Sweet']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Gyokuro Shuppin', 'gyokuro-shuppin', '', '玉露秀品', 'Gyokuro Shuppin is a premium variety of Japanese green tea, known for its exceptional quality and rich flavor. It is made from shade-grown tea leaves, similar to other high-end teas like matcha, but is carefully harvested and processed to maintain a delicate, sweet taste. Gyokuro Shuppin is prized for its smooth, umami-rich flavor, low astringency, and deep green color. The shading process increases the chlorophyll content, resulting in a tea that offers a complex, aromatic profile with hints of seaweed and a natural sweetness. It''s often considered one of the finest green teas in Japan. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 60, 2, 3, 'Use 4g per 100ml at 50–60°C. Steep 90–120 seconds; re-steep 2–3 times, raising temperature slightly.', ARRAY['Umami','Sweet']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Yame Gyokuro', 'gyokuro-yame', '', '八女玉露', 'Making the tea leaves for gyokuro is a very demanding process that requires great knowledge. The bushes are covered with straw mats 20 days before they are to be harvested and thereby develop a deep green leaf which gives a soft characteristic taste. Gyokuro means "pearl fog" and is among the finest of the Japanese teas. At Sing Tehus, we can offer several different Gyokuro teas, all of which are grown and produced according to the requirements that apply in Japan if you want to sell a tea under the name Gyokuro. Good Gyokuro has a deep and mellow taste also known as Umami. The nuances of taste will vary from product to product as different tea cultivars can be used for production. It is ...', '', 'green', 'true_tea', 'medium', 60, 2, 3, 'Use 4g per 100ml at 50–60°C. Steep 90–120 seconds; re-steep 2–3 times, raising temperature slightly.', ARRAY['Umami','Sweet']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Hadong Hwangcha', 'hadong-yellow-tea', '', '하동황차', 'This traditional Korean “yellow tea” (hwangcha) from Hadong is made by withering hand-picked spring leaves, rolling them, allowing a measured slow oxidation, then finishing with a gentle roast. The result is an elegant, amber liquor with layered aromas of honey, dried fruit (persimmon, jujube), chestnut and a hint of cocoa husk. The palate is smooth and rounded with very low bitterness, a soft, silky mouthfeel and a clean, comforting aftertaste. Ingredienser: gul te Western: 2–3 g per 200 ml · 90–92 °C · 2–3 min (2–3 infusions) Gongfu: 4–5 g per 100 ml · 92–95 °C · 20–25 s to start, then +10–15 sec. Cold brew: 6–8 g per 1 L cold water · 6–8 hours in the fridge', '', 'yellow', 'true_tea', 'medium', 75, 3, 3, 'Use 3g per 150ml at 70–75°C. Steep 2–3 minutes.', ARRAY['Sweet','Mellow']::text[], '{}'::text[], '#E6C84E', 15, 15, 20, 12, 'default', 'Teapp', NULL, TRUE),
('Haru Honoka', 'haru-honoka', '', '春ほのか', 'Haru Honoka is a blend where the sweetness and friendliness of the tencha tea meets the rounding sharpness and aroma of Fukamushi tea. A fresh green tea that helps set the mood for spring. Tencha is Japanese tea type usually used for making Matcha, where the leaves aren''t rolled into the typical needle shape, but left flat. Fukamushi tea is a tea type with a longer steaming process than usual. The result is a tea that resembles the ground of a forest, with the tightly rolled needles and flat tencha leaves providing a sensuous adventure for both the eyes and the palette. Ingredienser: grøn te Preparation of Haru honoka Haru honoka is best brewed in a preheated small teapot (or kyusu). Use ...', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Hojicha Gold', 'hojicha-gold', '', '焙じ茶', 'Hojicha Gold is a delicate tea, made by roasting spring Sencha tea leaves. It is exquisite in color and aromatic in fragrance, with a gently roasted buttery sunflower taste. Its mellow elegance makes it a perfect meal accompaniment. It is low in caffeine and therefore also an enchanting evening tea. Also well suited to be served with meals. Ingredienser: ristede grøn te', '', 'green', 'true_tea', 'medium', 95, 2, 3, 'Use 3g per 200ml at 95°C. Steep 2 minutes; hojicha is low in astringency and forgiving.', ARRAY['Roasty','Smooth']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Hokkyokusei', 'hokkyokusei-special-blend-sencha-tea', '', '北極星', 'Hokkyokusei is a Sencha tea and it consists of five cultivars. The blend is made especially for Sing Tehus by the Japanese tea master Yuta Hiraoka-san. Hiraoka-san visited Denmark in January 2024 and brought a range of tea samples from cultivars that are well suited to the Danish water. After an in-depth tea tasting in collaboration with the team at Sing Tehus, the result was Hokkyokusei, a mixture of cultivars that provide depth (umami) as well as a fresh and light tea with a hint of floral aroma. The tea consists of the following cultivars : 3 different varieties of Sencha Yabukita, 1 x Fukamushi Sencha Okumidori and 1 x Fukamushi Sencha Yabukita. The name Hokkyokusei means the North St...', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Hon Gyokuro Mare', 'hon-gyokuro-mare', '', '本玉露', 'Yame, Fukuoka prefecture, is one of the best areas for gyokuro production in Japan. This high quality, produced by Hoshino Seichaen, won the Nihoncha platinum award in 2016, which is one of the highest honours a tea producer can achieve. Dentou Hon Gyokuro - translated to traditional authentic gyokuro - shade-grown with honzu (rice straw mats) hand-picked and gently processed. This tea is produced in small quantities, once a year. The colour is deep green and the taste is deep umami. Store in a cool place. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 60, 2, 3, 'Use 4g per 100ml at 50–60°C. Steep 90–120 seconds; re-steep 2–3 times, raising temperature slightly.', ARRAY['Umami','Sweet']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Hwangcha', 'hwang-cha', '', '황차', 'Produced in extremely limited quantities by the artisan producers of Goyeonsanbang, this rare Korean Hwang Cha (Yellow tea) represents a remarkable expression of traditional craft tea. The leaves are carefully hand-picked and meticulously processed in small batches, using a demanding method that gently oxidizes the tea to reveal depth and elegance while preserving the vitality of the leaf. The leaves grow in a natural environment and are cultivated according to natural farming principles, where the surrounding biodiversity remains intact. Yellow tea is among the rarest tea styles, as its production requires great skill, patience, and careful control throughout the process. This tea comes ...', '', 'yellow', 'true_tea', 'medium', 75, 3, 3, 'Use 3g per 150ml at 70–75°C. Steep 2–3 minutes.', ARRAY['Sweet','Mellow']::text[], '{}'::text[], '#E6C84E', 15, 15, 20, 12, 'default', 'Teapp', NULL, TRUE),
('Jeju Gyul-hyang', 'ido-jeju-tangerine-peel-tea-50-gram', '', '귤향', 'Tangerine peel is an herbal tea, developed by Mr Chou in South Korea, which has gone through a fermentation process for 35 days. Good as evening tea. Nice orange flavour. Ingredienser: mandarinskal Brewing instructions 2g can be used 2-3 times (2-3 cups) or used for 1 liter of tea. The tea is equally good cold or hot.', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Herbal','Caffeine-Free','Citrusy']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Japanese Matcha, Yamabuki, top quality for Matcha latte', 'japanese-matcha-yamabuki-top-quality-for-matcha-latte', '', '', 'Matcha Yamabuki is a premium Japanese matcha, produced by Hoshino-Seichaen a family-run company located in Hoshino, Yame, Fukuoka. The area is famous for its production of high quality tea with rich umami and deep flavor notes. Matcha Yamabuki is perfect for matcha latte (don''t forget iced matcha latte), ice cream, desserts or in cold drinks like mock/cocktails. It can also be whipped like a traditional matcha with 80 degree hot water. Producing matcha is a difficult process, where entire fields are covered so that the bushes and fine tea leaves are not exposed to direct sunlight. After the leaves have been picked, they are processed through several stages, the last stage of which is to g...', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Kabuse Okumidori', 'kabuse-okumidori-sencha-for-cold-brew', '', 'かぶせ奥緑', 'This Kabuse Sencha (kabuse means shaded) is made from the much-loved Okumidori cultivar, which has a smooth and round flavour with low astringency. When you combine 5-day shade with the natural flavour of the cultivar, you have a seriously smooth and fresh sencha with white chocolate in the aftertaste. The tea is produced by "Clean Tea", Matsunosan in Shizouka, Japan. If you brew the tea in a HARIO cold brew bottle, add enough tea to the bottle to cover the bottom. Be careful not to use too much tea. Cold brew tea can stay fresh in the fridge for 1-2 days and you can make 2 extracts from the same leaves. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Kabusecha', 'kabusecha-shade-grown-2025', '', 'かぶせ茶', 'Kabusecha is a tea that has grown in the shade for approx. one week before picking. This causes the tea to have a sweeter and more nuanced taste and a juicier leaf develops. Japanese green tea can be enjoyed cold, as well as hot, as these teas have a mild and fresh taste. You can also brew the cold tea in cold water, but the leaves just have to steep for a longer time. This tea is from our producer Hoshino Seichaen in Yame, Fukuoka, Japan. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Hojicha-ko', 'koyamaen-hojicha-powder', '', '焙じ茶粉', 'Hojicha powder is made from a roasted green tea that is pulverized to a fine powder with a consistency similar to matcha. The fine powder has aromas of aromatic wood, cocoa and coffee and is great for using to make baked goods and desserts, ice cream, and Hojicha latte. The tea is produced by Marukyu Koyamaen, who is one of Japan''s most recognized tea producers, based in Uji, which is known for its unique tea of the highest quality. Ingredienser: Ristet grøn te', '', 'green', 'true_tea', 'medium', 95, 2, 3, 'Use 3g per 200ml at 95°C. Steep 2 minutes; hojicha is low in astringency and forgiving.', ARRAY['Roasty','Smooth']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Yuzu Kukicha', 'kukicha-with-yuzu', '', '柚子茎茶', 'Kukicha with yuzu, Kagoshima / Japan. Kukicha, or twig tea, is from Japan and is a mixture of stems and leaves from the tea bush. In this version of kukicha, the citrus fruit yuzu contributes, with citrus notes that also give deep flavour notes of orange/grapefruit and mint. Kagoshima is located on the southernmost tip of the island of Kyushu in southern Japan, the soil is mineral and the active volcano Sakurajima, has a strong influence on the surrounding nature. Ingredienser: grøn te, yuzu', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh','Citrusy']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Lady Chamomile With Pink Pepper And Rose Petals', 'lady-chamomile-with-pink-pepper-and-rose-petals', '', '', 'Lady Chamomile is an herbal tea containing chamomile, lemongrass, fennel, licorice root, rooibos, orange peel, lemon verbena, pink pepper and rose petals. An aromatic composition that adds freshness and sweetness to the mild taste of chamomile. Lady Chamomile is an herbal tea that is good at any time of the day and can be enjoyed hot or cold. Ingredienser: kamilleblomster 32 %, citrongræs 22 %, sød fennikel 8 %, rooibos 7 %, lakridsrod 7 %, appelsinskal 7 %, citronverbena 5 %, lyserød peber 3 %, rosenblade 2 %.', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Herbal','Caffeine-Free']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Laoman'e Shu Pu erh 2022', 'laomane-shu-pu-erh-2022', '', '', 'Grown in the wild forests on the high slope Bulang mountain the leaves of this unique shupu will give you an aromatic, meditative and layered tea that will be with you throughout your day for many brews, each time disclosing new herbal and botanics nuances, with prominent notes of walnuts and cacao beans in a thick smooth body. The tea leaves were harvested in Spring 2022 and stone-pressed in Autumn 2024. Ingredienser: fermenterede te Brewing guide EASTERN BREWING Quantity: 1 gr. of tea every 20/30 ml of water Rinse: before starting the infusion, rinse the leaves with a very fast washing in order to let them rehydrate and release a more intense brew. Gently cover the leaves with boiling w...', '', 'shou_puerh', 'true_tea', 'medium', 100, 4, 3, 'Rinse once with boiling water. Then 30–60 seconds per infusion; 6+ infusions.', ARRAY['Earthy','Smooth']::text[], '{}'::text[], '#6B4226', 100, 80, 88, 68, 'default', 'Teapp', NULL, TRUE),
('Lemon Buttermilk', 'lemon-buttermilk', '', '', 'Lemon buttermilk is a green tea, with added rose petals, lemon peel and the herb mallow, which is also used as a flavouring agent in marsh-mallow. It can be enjoyed both hot and cold, as it has a delicious taste. Tea with sweetness and citrus. A lovely sweet treat for any time of day. Ingredienser: grøn te (sencha), naturlig aroma, citronskal, roser, katost (urt)', '', 'blend', 'blend', 'medium', 95, 4, 3, 'Use 3g per 200ml at 95°C. Steep 3–4 minutes.', ARRAY['Aromatic','Citrusy']::text[], '{}'::text[], '#B07D56', 40, 30, 50, 40, 'default', 'Teapp', NULL, TRUE),
('Gabyul-cha', 'light-tea-fermented-herbs', '', '가별차', 'Light tea is a herbal tea, developed by Mr. Chou in South Korea. The tea consists of herbs that have gone through a fermentation process for 35 days. In this series there are 5 types (Relief tea, Goodnight etc.) and the complement each other well. 1 tea bag can be used 3 times (3 cups) or used for 1 liter of tea. The tea tastes very mild and is equally good cold or hot. 10 teabags in a bag. Net weight per teabag 1.2g Ingredienser: mandarinskal (60%) og kristtornblad (40%).', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Herbal','Caffeine-Free']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Liu'an Guapian', 'luan-guapian', '', '六安瓜片', 'Lu''an Guapian is one of the ten most famous teas in China, making it one of the most appreciated green teas. The name derives from the peculiar shape of the fresh leaves, that resemble small melon seeds - 瓜片 guapian in Chinese. It is cultivated near the famous Biānfú dòng , Bat Cave, the place of origin of Lu''an Guapian, on Dabie mountain. The young lady who tends to the plants of cultivar Jinyu n.1 is an expert in the pan-frying and charcoal drying processes that contributes to the great body and complexity of this tea, and her family has over 40 years of tea making experience. Lu''an Guapian is composed of only the first and second apical leaves, without any buds: even though this harves...', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Lunan Gushu Sheng 2022', 'lunan-ancient-trees-sheng-puer-2022', '', '布朗山古树生茶', 'This beautiful cake is composed of long, narrow, and fleshy leaves, stone-pressed in a compact round shape, tight yet so seemingly soft and gentle. A very distinct 2022 pu''er teas show great resemblance in character and appearance to more mature leaves except that, if over-brewed, an unmerciful astringency reminds us of their young age. The numerous full buds are covered in a snow of pure white fluff, which dances in the bright liquor with the first brews. When sipping the rich liquor, the same velvety and oily texture of our Nannuo Shengpu caresses the palate, yet it is here much fresher, although the dry leaves still possess the typical ripe apricot fragrance that belongs to and identif...', '', 'sheng_puerh', 'true_tea', 'medium', 100, 4, 3, 'Rinse once with boiling water. Then 30–60 seconds per infusion; 6+ infusions.', ARRAY['Earthy','Complex']::text[], '{}'::text[], '#8A9A3B', 60, 40, 70, 60, 'default', 'Teapp', NULL, TRUE),
('Yueguanbai 2026', 'lunan-ancient-trees-yueguanbai-white-tea-2026', '', '月光白', 'Ingredienser: hvid te Brewing guide EASTERN BREWING Quantity: 1 gr. of tea for every 30 ml of water Rinse: before starting the infusion, rinse the leaves with a very fast washing in order to let them rehydrate and release a more intense brew. Gently cover the leaves with warm water and pour it after a few seconds. Brewing time: Begin with a 30/40 seconds brew. Increase by 10 seconds with each successive brew. Water temperature: 85-90°C Number of brews: 10 WESTERN BREWING Quantity: 1 gr. of tea every 100 ml of water Brewing time: 2-3 minutes Water temperature: 85-90°C COLD BREW Quantity: 1 gr. of tea every 100 ml of water Brewing: put the tea leaves in room temperature water and steep for ...', '', 'white', 'true_tea', 'medium', 80, 4, 3, 'Use 3g per 200ml at 75–80°C. Steep 3–5 minutes; very forgiving, re-steep 2–3 times.', ARRAY['Floral','Sweet']::text[], '{}'::text[], '#C8C4B0', 10, 5, 12, 10, 'default', 'Teapp', NULL, TRUE),
('Lunan Gushu Sheng 2020', 'lunan-sheng-puer-ancient-trees-2020', '', '布朗山古树生茶', 'They strived and suffered, and they became the best-quality leaves. 2020 was a particularly dry year and this shortage of water caused a slowdown in the trees'' growth. However, the higher level of liquid sugar concentrated in the leaves provides with an amazing aroma, with a greater complexity. The freshness of the leaves is overwhelming, and the precious floral bouquet typical of its aftertaste is not long in coming, together with a surprising minerality and best of all, there is a great aging potential of these leaves. Eastern leaves decided to press them by stone and store them in traditional bamboo Ti, to ensure the best conservation for the years to come. Harvested by hand in Spring ...', '', 'sheng_puerh', 'true_tea', 'medium', 100, 4, 3, 'Rinse once with boiling water. Then 30–60 seconds per infusion; 6+ infusions.', ARRAY['Earthy','Complex']::text[], '{}'::text[], '#8A9A3B', 60, 40, 70, 60, 'default', 'Teapp', NULL, TRUE),
('Yueguangbai 2025', 'lunan-yueguangbai-stone-pressed-2025', '', '月光白', 'Harvested from ancient tea trees that have stood for over three centuries, this white tea is a reflection of time, strength, and quiet resilience. Season after season, the trees have shaped a personality that now pours into every cup. The 2025 spring harvest brings a tea of remarkable depth and clarity, with a long-lasting, nectar-like sweetness that evokes notes of ripe papaya and stone fruit. Its creamy texture and gentle floral undertones make each sip round and comforting, while the natural freshness lingers gracefully on the palate. The local cultivar, Menghai Dayezhong 勐海大叶种 , famous for the strength it brings to pu’er, here shows its softer side. That power hasn’t disappeared; it’s...', '', 'white', 'true_tea', 'medium', 80, 4, 3, 'Use 3g per 200ml at 75–80°C. Steep 3–5 minutes; very forgiving, re-steep 2–3 times.', ARRAY['Floral','Sweet']::text[], '{}'::text[], '#C8C4B0', 10, 5, 12, 10, 'default', 'Teapp', NULL, TRUE),
('Matcha Ajisai, Obubu, top quality for Matcha latte', 'matcha-ajisai-obubu-top-quality-for-matcha-latte', '', '', 'Matcha Ajisai is a high-quality culinary Matcha. It is made from the summer harvest of the Yabukita variety and is ground into a powder in a ball mill. With a distinct green colour, it is a perfect ingredient for matcha lattes, ice cream, desserts or in cold drinks such as mocktails/cocktails. The flavour profile is nuts, grass and kelp/seaweed it is slightly astringent with a good umami in the body. About the tea farmer Akihiro »Akky« Kita is the president and head farmer of Obubu. His desire to make tea accessible to the general public is the foundation of Kyoto Obubu Tea Farms. When Akky was in college, he took a part-time job as a farmhand in Wazuka and fell in love with the tea from ...', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Matcha Himawari, Hiraoka, top quality for Matcha latte', 'matcha-himawari-hiraoka-top-quality-for-matcha-latte', '', '', 'Matcha Himawari is a high quality culinary matcha made by tea producers Hiraoka. It is perfect for matcha latte, ice cream, desserts or in cold drinks like mock/cocktails. Producing matcha is a difficult process, where entire fields are covered so that the bushes and fine tea leaves are not exposed to direct sunlight. After the leaves have been picked, they are processed through several stages, the last stage of which is to grind the leaves into a very fine powder. Yuta Hiraoka-san has worked in the family business Tamakawa Tea since he was young, where he had a special interest in tea tasting and tea blending. Through dedication and hard work, in September 2023, as one of the youngest te...', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Matcha Meiju, Marukyu Koyamaen (Ceremonial)', 'matcha-meiju-marukyu-koyamaen-ceremonial', '', '', 'Specification: Origin : Uji, Kyoto Harvest: May 2026 tasting notes: umami, light and a sour hint Quality : Ceremonial grade (koicha and usucha) This matcha is produced by Koyamaen, a family-owned company in Uji, now run by the 8th generation. This matcha is one of the best the Kyoto region has to offer. The matcha tea is oriented towards a classic ''thick'' (koicha) matcha. It is soft and refined. Store dry and cool. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Matcha Mumon', 'matcha-mumon', '', '', 'This is a single-origin cultivar "Asahi" cultivated in both the "Okunoyama" and "Togawa" tea gardens, which are cultivated and managed by our garden, and processed, processed, and ground matcha. The "Asahi" variety is said to be the best of matcha, with excellent taste and aroma, and ranks highly at tea competitions every year. The "Asahi" variety we grow at our farm is named "Mumon" and has been well-received. Please enjoy its well-balanced flavor. Founded in 1879, Horii Shichimeien continues to cultivate the renowned 600-year-old Okunoyama Tea Garden, the sole remaining tea garden of Kyoto’s historic “seven beautiful gardens”. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Matcha Narino - 20g (Ceremonial)', 'matcha-narino-20g-ceremonial', '', '', 'This matcha stands in a class of its own. Crafted exclusively from the Narino cultivar, it reflects the rich legacy of the Okunoyama Tea Garden. This tea embodies excellence, offering a deep umami flavor with remarkably low bitterness. Indulge in a matcha experience that bridges centuries of tradition and the pinnacle of Japanese tea artistry. Founded in 1879, Horii Shichimeien continues to cultivate the renowned 600-year-old Okunoyama Tea Garden, the sole remaining tea garden of Kyoto’s historic “seven beautiful gardens”. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Matcha Oju, Marukyu Koyamaen (Ceremonial)', 'matcha-oju-marukyu-koyamaen-ceremonial', '', '', 'Specification: Origin : Uji, Kyoto Harvest: May 2026 tasting notes: umami, light and a sour hint Quality : Ceremonial grade ( koicha and usucha ) This matcha is one of the best the Kyoto region has to offer, oriented towards a classic ''thick'' ( koicha ) matcha. It is soft and refined. Store dry and cool. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Matcha Uji Mukashi', 'matcha-uji-mukashi', '', '', 'The owner of the garden carefully selects high-quality tencha from the tencha-producing areas in Kyoto Prefecture. This matcha has the aroma and flavor of freshly ground tea and is easy to drink. It is often used as a thin tea at tea ceremonies. It tastes even better when drunk with sweets. It is also recommended for use in making sweets. Horii Shichimeien, founded in 1879, still manage the 600-year-old Okunuoyama Tea Garden in Uji, Kyoto. This garden is the only survivor of 7 historic tea gardens in Kyoto. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Matcha Unkaku, Marukyu Koyamaen (Ceremonial)', 'matcha-unkaku-marukyu-koyamaen-ceremonial', '', '', 'Origin : Uji, Kyoto Harvest: May 2026 Tasting notes: deep umami, light sweetness and soft and round Quality : ceremonial grade, for thick tea This matcha is one of the best the Kyoto region has to offer, oriented towards a classic ''thick tea'' matcha. A thick tea matcha is also called koicha, and is referred to as the formal tea made at special celebrations. It is incredibly soft and refined but stands out with its own well-known flavour character. Store dry and cool. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Matcha Wako, Marukyu Koyamaen (Ceremonial)', 'matcha-wako-marukyu-koyamaen-ceremonial', '', '', 'Specification: Origin: Uji, Kyoto Harvest: May 2026 Tasting notes: deep umami, light sweetness and a hint of sourness Quality: 5 out of 5 This matcha is one of the best the Kyoto region has to offer, oriented towards a classic thin tea matcha. It is incredibly soft and refined but stands out with its own well-known flavour character. Store dry and cool. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Jin Xuan', 'milky-oolong', '', '金萱', 'Milky Oolong is a semi-oxidized tea known for its creamy aroma and naturally soft flavor. Its golden infusion reveals subtle creamy notes and warm florals, offering a soothing and harmonious tea experience. Milky Oolong is one of our most popular teas, since its also very suitable for cold brew. The leaves undergo a brief oxidation, which is carefully interrupted through drying to preserve the freshness and bright character of green tea. During processing, the leaves are gently sun-wilted, enhancing their natural sweetness and creating the tea’s smooth, comforting profile. Oolong teas like this are always made from whole leaves and originate primarily from China and Taiwan—regions renowne...', '', 'oolong', 'true_tea', 'medium', 90, 3, 3, 'Use 5g per 100ml at 90–95°C. Quick rinse, then 45–90 seconds per infusion; 5+ infusions.', ARRAY['Floral','Creamy']::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE),
('Mizudashi Sencha', 'mizudashi-sencha-with-matcha-for-cold-brew-iced-tea', '', '水出し煎茶', 'Sencha is the tea that is drunk the most in Japan. It is very popular because of the clean fresh taste. Sencha is mostly enjoyed hot but can also be prepared as iced tea. Cold sencha is fresh and mouth-watering and is an excellent alternative to other cold drinks on a hot summer day. Light, clear, fresh taste. Ingredienser: grøn te Net weight: 18 x 5 grams.', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Mugicha', 'mugi-cha-japanese-barley-tea', '', '麦茶', 'Barley tea (mugicha) is an old tradition in Japan when you need a relaxing hot drink. This mugi-cha is from Hida, located in Gifu, produced by “Nabeshimameicha”, a long-established tea company with a history of over 100 years. The quality of Hida Barley Tea is rooted in the carefully cultivated barley grown by Mr. Tanaka, one of their trusted farmers. Farmers often face challenges due to unfair pricing. At Nabeshimameicha, they ensure fair transactions by purchasing the high-quality barley from award-winning farmers, such as those who have received the Japan Agricultural Award, at a fair price and in predetermined quantities. Through this initiative, we believe we are also contributing to...', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Nutty','Toasty']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Yueguangbai 2026', 'nannuo-forest-trees-yueguangbai-white-tea-2026', '', '月光白', 'This tea is cultivated and cared for by Eastern leaves. Grown protected by mountain fog, the leaves of this Yueguangbai 月光白 (Moonlight) white tea carry the purest expression of a high mountain forest. Harvested in early spring 2026, these big yet tender leaves bloom in their wild forest on Nannuo Mountain, where 40–50 year-old tea trees grow naturally in the shaded underwood. These trees, nourished by a rich biodiversity, lend their leaves remarkable clarity and depth. In gongfucha, this white tea reveals all the fresh floral fragrances of a young Yueguangbai, with hints of fruity delicacy and tropical citrus notes followed by a clear honey sweetness. Vibrant and creamy in the mouthfeel, ...', '', 'white', 'true_tea', 'medium', 80, 4, 3, 'Use 3g per 200ml at 75–80°C. Steep 3–5 minutes; very forgiving, re-steep 2–3 times.', ARRAY['Floral','Sweet']::text[], '{}'::text[], '#C8C4B0', 10, 5, 12, 10, 'default', 'Teapp', NULL, TRUE),
('Nannuo Yesheng Sheng 2012', 'nannuo-sheng-puer-wild-forest-2012', '', '南糯山野生生茶', 'The fresh leaves of this special Pu''er Sheng pu were harvested in Spring 2012 and pressed in 2019. They were allowed ferment naturally for seven years surrounded by the beautiful landscape of Nannuo mountain, before pressing them and locking their unique fragrance in time. They have been pressed by stone, to guarantee the best quality both now and in the years to come. By infusing the leaves, one can still feel the quiet seclusion of spring rain and the fresh mountain air, with a warm underwood aftertaste which is typical of the fermentation process. Tasting this tea is just like entering a forest surrounded by mist: a hue of wet soil, tree bark, and moss is released after the first brew,...', '', 'sheng_puerh', 'true_tea', 'medium', 100, 4, 3, 'Rinse once with boiling water. Then 30–60 seconds per infusion; 6+ infusions.', ARRAY['Earthy','Complex']::text[], '{}'::text[], '#8A9A3B', 60, 40, 70, 60, 'default', 'Teapp', NULL, TRUE),
('Kuro Gyokuro', 'natural-black-gyokuro', '', '黒玉露', 'With an exquisite floral palate, this black tea from Obubu Tea Farms is made from the highest grade of shaded tea leaves. The producer is always experimenting with new techniques, resulting in wonderful teas unlike any others. It combines the umami rich tea leaves usually used for green Gyokuro tea, with the oxidation process of black tea, resulting in an entirely unique tea: Black Gyokuro. Shaded from the sun for three weeks before its spring harvest, the raw material is the highest quality before undergoing black tea processing. This Black Gyokuro also provides a unique opportunity to taste a tea which is new to the world. Exactly how to brew this new tea type remains an open question. ...', '', 'black', 'true_tea', 'medium', 95, 3, 3, 'Use 3g per 200ml at 90–95°C. Steep 3–4 minutes.', ARRAY['Umami','Sweet']::text[], '{}'::text[], '#8B4513', 90, 70, 78, 55, 'default', 'Teapp', NULL, TRUE),
('Okumidori Matcha (Organic)', 'natural-okumidori-matcha-25g-tin-ceremonial', '', '奥緑', 'Rich and savoury, Natural Okumidori is fresh and sweet with a creamy texture, this tea is a favourite among our staff members. Rich green in the cup, it has a subtle coconut aroma. Made by slowly grinding Tencha leaves from the first harvest of the year on a stone mill, this is a magnificent Ceremonial Grade Matcha. Obubu Tea Farms is a family-owned tea farm located in Wazuka, Kyoto Prefecture, Japan, renowned for its dedication to traditional, sustainable tea cultivation. The farm produces high-quality, organic Japanese teas, including sencha, matcha, and hojicha, with a strong emphasis on preserving the environment and maintaining a connection to local tea heritage. Obubu also offers im...', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Genmai', 'obubu-genmai-roasted-brown-rice', '', '玄米', 'We isolated Genmaicha''s lovely roasted rice and created Genmai. Made by roasting mochi rice, it is sweeter and crispier than regular rice. You can add this Genmai to any tea of your choice, creating a original sibling of Genmaicha. Genmai can also be added as a satisfying garnish to salads, soups, sandwiches or even eaten alone as a healthy snack. Ingredienser: ristet brun ris Net weight: 80 grams.', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Nutty','Toasty']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Ofelia Tea', 'ofelia-tea', '', '', 'Ofelia tea is a rich black tea with apricot, vanilla and cornflower. Ofelia tea is a great afternoon tea with a biscuit as it has a rich flavour and sweetness. Ingredienser: sort te, rosenblade, kornblomst, solsikkeblade, vanilje, abrikos.', '', 'blend', 'blend', 'medium', 95, 4, 3, 'Use 3g per 200ml at 95°C. Steep 3–4 minutes.', ARRAY['Aromatic']::text[], '{}'::text[], '#B07D56', 40, 30, 50, 40, 'default', 'Teapp', NULL, TRUE),
('Okumidori Matcha', 'okumidori-matcha-25g-tin-ceremonial', '', '奥緑', 'Rich and savory, Okumidori is delicately sweet with underlying elements of green pea and mango. Jade-green in the cup, it has a subtle coconut aroma. Made by slowly grinding Tencha leaves from the first harvest of the year on a stone mill, this is a magnificent Ceremonial Grade Matcha. Obubu Tea Farms is a family-owned tea farm located in Wazuka, Kyoto Prefecture, Japan, renowned for its dedication to traditional, sustainable tea cultivation. The farm produces high-quality, organic Japanese teas, including sencha, matcha, and hojicha, with a strong emphasis on preserving the environment and maintaining a connection to local tea heritage. Obubu also offers immersive tea experiences, allowi...', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Organic "Yellow" Pumpkin And Turmeric', 'organic-yellow-pumpkin-and-turmeric', '', 'Yellow', 'Yellow is a great alternative as an evening tea as well as a refreshing tea that can be enjoyed around the clock. It''s also great for children. Yellow is a "veggie tea" as it consists of both herbs and vegetables. Can be enjoyed both hot and cold. Ingredienser: ( *=økologisk ) gulerod*, æble*, havtorn*, ingefær*, gurkemeje*, appelsin*, græskar*, anis*, naturlig aroma. *DK-ØKO-100. *Non-EU agriculture', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Herbal','Caffeine-Free']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Benifuki', 'organic-benifuki', '', 'べにふうき', 'Benifuki is a distinguished Japanese black tea hailing from the fertile volcanic soil of Kagoshima, renowned for its robust flavor and aromatic depth. Crafted from the Benifuki cultivar, this tea offers a harmonious balance of maltiness and subtle floral notes, making it a delightful choice for both seasoned tea enthusiasts and newcomers alike. Ingredienser: (*=økologisk) *sort te. *DK-ØKO-100. *Not EU agriculture Organic Black Tea from Kagoshima, (Benifuki) can be brewed in a medium large teapot. Water temperature: 95 degrees celcius 1. Brew: 3 minutes 2. Brew :1-2 minutes', '', 'black', 'true_tea', 'medium', 95, 3, 3, 'Use 3g per 200ml at 90–95°C. Steep 3–4 minutes.', ARRAY['Bold','Malty']::text[], '{}'::text[], '#8B4513', 90, 70, 78, 55, 'default', 'Teapp', NULL, TRUE),
('Hei Moli Zhucha', 'organic-black-jasmine-pearls', '', '黑茉莉珠茶', 'Jasmine pearls consist of very high quality black tea. The addition of jasmine aroma takes place by layering jasmine flowers between the tea leaves. In this way, the leaves absorb the aroma from the flower. Jasmine tea is the oldest aromatic tea in China. It was invented during the Ming Dynasty (years 1368-1644) and is very popular to this day. This Jasmine tea is made in the original and classic, where the tea leaves are store together with fresh jasmine flower, naturally absorbing their floral aroma. They are then rolled into beautiful small pearls that unfold as the tea is brewed. With natural Jasmine aroma, sweet and fresh. A perfect balance of Jasmine and mild black tea. Ingredienser...', '', 'black', 'blend', 'medium', 95, 3, 3, 'Use 3g per 200ml at 90–95°C. Steep 3–4 minutes.', ARRAY['Floral','Perfumed']::text[], '{}'::text[], '#8B4513', 90, 70, 78, 55, 'default', 'Teapp', NULL, TRUE),
('Shui Xian', 'organic-china-leaf-oolong-shui-xian', '', '水仙', 'China Leaf Oolong is a dark oolong tea in the "yancha style". Yancha means rock tea in Chinese, i.e. tea bushes that grow on rocks. These teas have a slightly sweet round full flavor with notes of dried fruit, tobacco and mineral aftertaste. Oolong is a semi-oxidized tea, i.e. something in between a green and a black tea. During processing, the leaves have briefly begun an oxidation process, which has been interrupted by drying in order to preserve the properties and bright color of the green tea. The leaves oxidize in the sun, which produces an endearing taste experience. The oolong teas are always whole leaves and mainly originate from Taiwan and China. Ingredienser: ( *= økologisk ) *o...', '', 'oolong', 'true_tea', 'medium', 90, 3, 3, 'Use 5g per 100ml at 90–95°C. Quick rinse, then 45–90 seconds per infusion; 5+ infusions.', ARRAY['Floral','Creamy']::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE),
('Organic Darjeeling 2nd Flush', 'organic-darjeeling-2nd-flush', '', '', 'High in the Indian Himalayas, the Darjeeling region is renowned for producing elegant and nuanced teas. The second flush is the season’s second harvest, where the leaves mature under more sun and warmth—resulting in a tea with greater depth and aroma. This Darjeeling has a complex yet delicate flavor, with the classic muscatel notes the region is known for. Smooth, mild, and rounded, it’s a refined tea—perfect for a quiet afternoon moment. Ingredients: (*=organic) *black tea. *DK-ØKO-100. *Not EU agriculture', '', 'black', 'true_tea', 'medium', 95, 3, 3, 'Use 3g per 200ml at 90–95°C. Steep 3–4 minutes.', ARRAY['Bold','Malty']::text[], '{}'::text[], '#8B4513', 90, 70, 78, 55, 'default', 'Teapp', NULL, TRUE),
('Organic Earl Grey With Blue Cornflowers', 'organic-earl-grey-with-blue-cornflowers', '', '', 'This Earl Grey is milder in taste than our classic Earl Grey teas. It has a fine and mild bergamot flavor and a floral, almost anise aftertaste, from the blue cornflower. Earl Grey is named after Earl Charles Grey, who was Prime Minister under King William IV at the beginning of the 19th century century. Legend has it that the earl was given the recipe by a Chinese mandarin who was his friend and whose life he had saved. Round and mild taste. Ingredienser: ( *= økologisk ) *sort te, *bergamotolie, *kornblomst *DK-ØKO-100. *Non-EU agriculture', '', 'blend', 'blend', 'medium', 95, 4, 3, 'Use 3g per 200ml at 95°C. Steep 3–4 minutes.', ARRAY['Citrusy','Bold']::text[], '{}'::text[], '#B07D56', 40, 30, 50, 40, 'default', 'Teapp', NULL, TRUE),
('Jin Hou Hongcha', 'organic-golden-yunnan', '', '金猴红茶', 'In the south-western and densely forested part of China lies the Yunnan province - the birthplace of the tea plant. Tea has been cultivated for over 1700 years and the area''s climate is ideal for producing high quality tea. It is believed that the tea plant Camelia Sinensis has always grown wild in the Yunnan area. "Yun" means cloud and this refers to the very high humidity that characterises Yunnan. With a high proportion of the valuable and sweet golden tips, this black tea has a powerful flavour with pleasant malt notes and is slightly smoky. Suitable for morning and afternoon tea with the addition of milk to taste. Ingredienser: ( *= økologisk ) *sort te *DK-ØKO-100. *Non-EU agriculture', '', 'black', 'true_tea', 'medium', 95, 3, 3, 'Use 3g per 200ml at 90–95°C. Steep 3–4 minutes.', ARRAY['Bold','Malty']::text[], '{}'::text[], '#8B4513', 90, 70, 78, 55, 'default', 'Teapp', NULL, TRUE),
('Organic Greek Mountain Tea', 'organic-greek-mountain-tea', '', '', 'Sideritis is the Greek name for this plant which is quite widespread in the Mediterranean region and the countries along the Adriatic Sea, where it has been popular since ancient times. Græsk Bjerg tea has a spicy and slightly sweet taste and can be enjoyed both cold and hot. Add any a little honey and lemon if desired. Ingredients: ( *= organic ) *Sideritis Syrica ( Greek mountain tea ) *DK-ÖKO-100 *Not EU agriculture', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Herbal','Bright']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Organic Greek Mountain Tea With Orange', 'organic-greek-mountain-tea-with-orange', '', '', 'Greek Mountain Tea also known as Sideritis is a common plant in the Mediterranean region. Here in an exciting and flavourful combination of orange peel, nettle, flowers and lemongrass. Organic Greek Mountain Tea with orange is also particularly good as an iced tea. Ingredients: ( *= organic ) *Sideritis Syrica ( Greek Mountain Tea ) 31%, *Stinging Nettle, *Lemongrass, *Orange Peel 14%, *Lime Blossom, *Mormon Fruit, *Camomile, natural bergamot flavour. *DK-ØKO-100. *Non-EU agriculture', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Herbal','Bright']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Organic Indian Chai', 'organic-indian-chai', '', '', 'Chai is the name for tea in several countries. It is a centuries-old drink that has played an important role in many cultures. Chai is a spiced milk tea in India, and its popularity is increasing in the rest of the world. The ingredients usually consist of: Strong black tea, fat milk, a combination of various spices and sweetener. The spices vary from region to region among households in India. The most used are cardamom, cinnamon, ginger, cloves and pepper. Indian Chai produces a calming and warming effect, acts as a natural digestive aid and leaves a wonderful feeling of relaxation. Ingredienser: ( *= økologisk) *sort te, *kardemomme, *kanel, * ingefær, *nelliker, *peber *DK-ÖKO- 100. *...', '', 'blend', 'blend', 'medium', 95, 4, 3, 'Use 3g per 200ml at 95°C. Steep 3–4 minutes.', ARRAY['Spicy','Bold']::text[], '{}'::text[], '#B07D56', 40, 30, 50, 40, 'default', 'Teapp', NULL, TRUE),
('Qing Xin Oolong', 'organic-jade-oolong', '', '青心烏龍', 'The tea also goes by the name Dung Ti Jade Oolong. The designation Jade Oolong refers to the fact that this Oolong tea is a green Oolong. The tea is oxidized quite lightly, which results in a tea with a very soft taste character and floral notes such as lily and orchid. The tea has a complex taste. The green-blue teabags are rolled into small balls which unfold beautifully during brewing. Ingredienser: (*=økologisk) *oolong-te (halvoxideret te) *DK-ØKO-100 *Not EU agriculture', '', 'oolong', 'true_tea', 'medium', 90, 3, 3, 'Use 5g per 100ml at 90–95°C. Quick rinse, then 45–90 seconds per infusion; 5+ infusions.', ARRAY['Floral','Creamy']::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE),
('Kagoshima Matcha No. 90', 'organic-kagoshima-matcha-no-90', '', '鹿児島抹茶', 'Cultivated in Kagoshima’s fertile volcanic landscape, this organic matcha offers a refined, well-balanced profile. Shaded before harvest and carefully processed to preserve its vibrant hue and smooth taste, No. 90 features delicate green notes and a gentle sweetness, perfect for matcha latte, drinks, desserts and ice cream. Ingredienser: Økologisk grøn te', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Organic Keemun', 'organic-keemun', '', '', 'Keemun Tea has a relatively short history, as it was produced for the first time in 1875. It originates from Qimen in the Anhui province in central China, where for many hundreds of years green tea until an official named Yu Quianchen came home from a trip to Fujian province, where he had learned all about black tea production. Keemun is the most sought-after tea in England and considered by many to be one of the world''s finest black teas. A milder tea, with a rich, sweet aroma of roses and lovely fragrant taste. Keemun can be added to milk. Ingredients: ( *= organic) * black tea *DK-ØKO-100. *Not EU agriculture', '', 'black', 'true_tea', 'medium', 95, 3, 3, 'Use 3g per 200ml at 90–95°C. Steep 3–4 minutes.', ARRAY['Bold','Malty']::text[], '{}'::text[], '#8B4513', 90, 70, 78, 55, 'default', 'Teapp', NULL, TRUE),
('Organic Korean Sejak', 'organic-korean-sejak', '', '', 'South Korean green tea from the volcanic island of Jeju Do. Thanks to the island''s nutrient-rich volcanic soil, the conditions for tea cultivation are ideal. This tea differs from many other green teas by being both steamed and pan-roasted. Steaming green tea is a Japanese technique, which means that the steaming means that the tea does not oxidize and therefore remains green tea. In China, it is most common to roast the tea in a wok to stop oxidation. Since the Sejak tea here is both steamed and roasted, the taste brings to mind both Japanese and Chinese tea. Harmonious fresh tea with notes of young beech leaves, manna, umami. Ingredienser: økologisk grøn te. DK-ÖKO-100. Non-EU agriculture', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Organic Mint Blend', 'organic-mint-blend', '', '', 'Classic mint blend tea, which combines the refreshing, cool flavors of both mint varieties. Spearmint offers a mild, sweet taste, while peppermint adds a sharper, invigorating coolness. This soothing tea is perfect for a calming yet energizing experience, with natural properties that aid digestion and promote relaxation. Ideal for any time of day, it''s both refreshing and revitalizing, with a delightful balance of minty goodness. Ingredienser: (*=økologisk) *pebermynte 50 %, grøn mynte 50 % * DK-ÖKO-100 *Not EU agriculture', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Minty','Refreshing']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Yunnan Hong', 'organic-muscatel-dragon-yunnan', '', '滇红', 'Muscatel Dragon is a black tea which originates from the Chinese province of Yunnan, where it has been grown for almost 1700 years and the area''s climate is ideal for producing high quality tea. Muscatel dragon tea leaves are lightly rolled and have a fine spicy aroma and a pleasant warm taste with an aftertaste of roses. The high quality of the tea leaf, results in a tea that won’t turn bitter if you leave it brewing slightly too long. Ingredienser: økologisk sort te', '', 'black', 'true_tea', 'medium', 95, 3, 3, 'Use 3g per 200ml at 90–95°C. Steep 3–4 minutes.', ARRAY['Bold','Malty']::text[], '{}'::text[], '#8B4513', 90, 70, 78, 55, 'default', 'Teapp', NULL, TRUE),
('Organic Pan Yong "Golden Monkey"', 'organic-pan-yong-golden-monkey', '', 'Golden Monkey', 'Pan yong tea is grown at an altitude of 1200 m on hillsides in Fujian province in China. Tea has been cultivated here for 1700 years, as the weather conditions are optimal for tea cultivation, with moist soil, rich in hours of sunshine and mist. However, the impassable terrain has presented some challenges over the years, which is why monkeys have historically been used to help with the picking, hence the name. However, Pan yong is a relatively new type, which is picked in the spring. It consists of light shoots and leaves, which contributes to the golden taste, with notes of honey in the aftertaste. An exceptionally beautiful and elegant tea. Fine and round taste, without unpleasant bitt...', '', 'black', 'true_tea', 'medium', 95, 3, 3, 'Use 3g per 200ml at 90–95°C. Steep 3–4 minutes.', ARRAY['Bold','Malty']::text[], '{}'::text[], '#8B4513', 90, 70, 78, 55, 'default', 'Teapp', NULL, TRUE),
('Shou Puer', 'organic-pu-erh-ripe-in-loose-weight', '', '熟普洱', 'Pu Erh tea is in a category of its own, as this tea has gone through a fermentation process. It originally comes from southern China, specifically Yunnan. The production of Pu Erh differs from the production of green and black tea, as the leaves are fermented with water over a period of 40 – 50 days. Finally, the fermentation is stopped with drying in 150 degrees hot air. With its characteristic taste of forest soil and reddish brown color, Pu Erh tea is an exquisite experience. This is a tea well-suited for several infusions. Deep, characteristic taste of autumn and forest soil. Ingredienser: (*=økologisk) *fermenteret te *DK-ÖKO-100. *Not EU agriculture', '', 'shou_puerh', 'true_tea', 'medium', 100, 4, 3, 'Rinse once with boiling water. Then 30–60 seconds per infusion; 6+ infusions.', ARRAY['Earthy','Smooth']::text[], '{}'::text[], '#6B4226', 100, 80, 88, 68, 'default', 'Teapp', NULL, TRUE),
('Organic Sencha Kirishima', 'organic-sencha-kirishima', '', '', 'This Organic Sencha comes from the mountain area of Kirishima in Kagoshima Japan. Kagoshima in southern Japan is known for their tea production and especially the production of organic tea in which they are a leader. Here the soil is mineral and the active volcano Sakurajima, has a strong influence on the surrounding nature. Organic Sencha Kirishima is from the tea producer Henta Seicha and the carefully selected tea leaves are from the first harvest of the year where the best leaves can be found. The tea is a mixture of two tea cultivars, Saemidori and Yabukita, this helps to give the tea a deeper and more complex taste that brings to mind grass, seaweed and melon. Ingredienser: økologis...', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Organic Sencha Oritaen', 'organic-sencha-oritaen', '', '', 'This Organic Sencha comes from the southern tip of Kagoshima in Japan. Kagoshima in southern Japan is known for their tea production and especially the production of organic tea in which they are the leader. Here the soil is mineral and the active volcano Sakurajima, has a strong impact on the surrounding nature. Organic Sencha Orita is from the tea producer Oritaen and the carefully selected tea leaves are from the first harvest of the year where the best leaves can be found. The tea is a mixture of two tea cultivars, Okumidori and Kanayamidori, this helps to give the tea a rich taste with good umami and more complexity that brings to mind baby cabbage, seaweed and asparagus. Ingrediense...', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Organic Sencha w/ Summer Flowers', 'organic-sencha-w-summer-flowers', '', '', 'Sencha is a popular green tea with a gentle and fresh taste. The sencha types that grow in China lend themselves well to a combination with flowers. This tea has a hint of passion fruit in the aftertaste. Elegant tea with marigold and cornflower. Ingredienser: (*=økologisk) *grøn te, *morgenfrue blomster, *kornblomst blomster, naturlig aroma *DK-ØKO- 100 *Non-EU agriculture', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Organic Sing Herbal Mint, Herbs And Licorice Root.', 'organic-sing-herbal-mint-herbs-and-licorice-root', '', '', 'Organic Sing Herbal Mint is a fresh, refreshing and flavoursome herbal tea. The combination of lemongrass, liquorice root, mint and apple pieces creates a smooth flavour experience with many delicate nuances. Can be enjoyed at any time of day or night and also particularly good as an iced tea. Ingredienser: ( *= økologisk ) *citrongræs, *lakridsrod 38 %, *mynte, *æblebiter. *DK-ØKO-100. *Non-EU agriculture', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Minty','Refreshing']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Organic White and Green Tea with Rosehip and Elderflower', 'organic-white-and-green-tea-with-rosehip-and-elderflower', '', '', 'A delicate infusion of white and green tea forms the base of this naturally sweet and gently aromatic blend. Herbal notes of fennel, anise, and liquorice root lend a soft, comforting warmth, while rosehip adds a subtle tart brightness. Fenugreek seeds and nettle brings depth and nourishing qualities, beautifully balanced by the floral lightness of elderflower. Perfect for calming the senses and supporting well-being, this tea is a gentle daily ritual in a cup. Ingredienser: Økologisk hvid te, fennikel, grøn te, anis, hyben (6,9 %), lakridsrod, brændenældeblade, bukkehornfrø og hyldeblomst (0,4 %) Ingredients: Organic white tea, fennel, green tea, anise, rosehip (6.9%), liquorice root, net...', '', 'white', 'true_tea', 'medium', 80, 4, 3, 'Use 3g per 200ml at 75–80°C. Steep 3–5 minutes; very forgiving, re-steep 2–3 times.', ARRAY['Floral','Sweet']::text[], '{}'::text[], '#C8C4B0', 10, 5, 12, 10, 'default', 'Teapp', NULL, TRUE),
('Bai Fenghuang', 'organic-white-phoenix', '', '白凤凰', 'Beautiful white tea form Yunnan in China. Its an e arly-picked tea of high-grade leaves with many young, silvery needles. The leaves are withered and dried in the sun which gives is a round vegetal and mildly sweet tasting tea. Ingredienser: økologisk hvid te DK-ØKO-100. Non-EU agriculture', '', 'white', 'true_tea', 'medium', 80, 4, 3, 'Use 3g per 200ml at 75–80°C. Steep 3–5 minutes; very forgiving, re-steep 2–3 times.', ARRAY['Floral','Sweet']::text[], '{}'::text[], '#C8C4B0', 10, 5, 12, 10, 'default', 'Teapp', NULL, TRUE),
('Organic White tea with geranium and elderflower', 'organic-white-tea-with-geranium-and-elderflower', '', '', 'This elegant white tea is a Pai Mu Tan from Fujian, the birthplace of the traditional white tea craft. Revered for centuries, the region’s gentle processing preserves the leaf’s natural character and refined complexity. In this blend, the soft, silvery leaves are paired with a carefully selected array of herbs and blossoms, creating a graceful evolution of our earlier elderflower tea. The infusion is smooth and delicate, offering a light-bodied cup layered with subtle floral notes, a silky texture, and a lingering, fragrant finish. Ingredienser: ( *= økologisk) Hvid te* 78,8% , brændenældeblade * 10%, birkeblade* 9%, hyldeblomst* 1%, morgenfrue kronblade * 1%, naturlig hyldebærblomstsarom...', '', 'white', 'true_tea', 'medium', 80, 4, 3, 'Use 3g per 200ml at 75–80°C. Steep 3–5 minutes; very forgiving, re-steep 2–3 times.', ARRAY['Floral','Sweet']::text[], '{}'::text[], '#C8C4B0', 10, 5, 12, 10, 'default', 'Teapp', NULL, TRUE),
('Oyatoko no Hojicha', 'oyatoko-no-hojicha', '', 'オヤトコの焙じ茶', 'Oyatoko is the raw material of hojicha, which is harvested together with the leaves (parents) that are full of nutrients from the previous year and the new shoots (children) that have grown from them. Please enjoy the scent and taste of hojicha. The have a soft and round taste, and the roasting adds a nutty taste. Hojicha is a very popular food tea in Japan, as it is both sweet and mouth-watering. It''s a really nice autumn tea to cozy up to. Horii Shichimeien, founded in 1879, still manage the 600-year-old Okunuoyama Tea Garden in Uji, Kyoto. This garden is the only survivor of 7 historic tea gardens in Kyoto. Ingredienser: Ristet grøn te', '', 'green', 'true_tea', 'medium', 95, 2, 3, 'Use 3g per 200ml at 95°C. Steep 2 minutes; hojicha is low in astringency and forgiving.', ARRAY['Roasty','Smooth']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Pai Mu Tan with Nettle, Apple and Cornflower', 'pai-mu-tan-with-nettle-apple-and-cornflower', '', '', 'White tea with nettle and apple is a tea developed by Sing Tehus. It is a type of flavoured tea where the tea is combined with Nordic elements such as nettle and apple. We are trying to expand the possibilities of combining tea with natural flavours. The white tea is a Pai Mu Tan, which is naturally dried in the sun, which gives it more body and depth. It''s a perfect summer tea as it can also be enjoyed cold. Ingredienser: brændenælde (76,5 %), hvid te, kornblomster (2 %) og naturlig aroma (æble) 1,5 %.', '', 'white', 'true_tea', 'medium', 80, 4, 3, 'Use 3g per 200ml at 75–80°C. Steep 3–5 minutes; very forgiving, re-steep 2–3 times.', ARRAY['Floral','Sweet']::text[], '{}'::text[], '#C8C4B0', 10, 5, 12, 10, 'default', 'Teapp', NULL, TRUE),
('Gyokuro Kiwami', 'premium-gyokuro-kiwami', '', '玉露極', 'This Gyokuro Kiwami from Yame -Hoshino in Japan is a top class tea. The tea is shade-grown, which helps the leaves retain their juices and fine flavours. When the leaves are ready to be harvested, they are hand-picked, which is a laborious process, but a conscious choice as it produces a much finer tea. A tea with a great texture, softness and, not least, plenty of umami flavour, which is a hallmark of high-quality Gyokuro tea. The tea is packed in 5 bags of 5 grams each (25 grams in total) in a nice wooden box. The individual packed bags, means you are in no hurry to finish a whole bag, as each they are packed in individual portions. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 60, 2, 3, 'Use 4g per 100ml at 50–60°C. Steep 90–120 seconds; re-steep 2–3 times, raising temperature slightly.', ARRAY['Umami','Sweet']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Shincha No. 120', 'premium-shincha-no-120-2026', '', '新茶', 'Japanese shincha tea, also known as "new tea" or "first flush tea", offers a unique and vibrant taste that captures the essence of spring. We have selected three Shincha teas that have different characters and flavor nuances, as they consist of different cultivars. Shincha teas are distinguished by being extremely fresh and all Shincha teas have flavor notes such as: asparagus, fresh grass, sea/seaweed and umami. Read a detailed explanation below. Premimu shincha consists of the following cultivars: Saemidori. . Cultivar characteristica: Saemodori : Bright green in color, elegant fragrance good umami and less astringent. This cultivar is often used for high end shincha/sencha, gyokuro and...', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Pungwol-cha', 'relief-tea-fermented-herbs', '', '풍월차', 'Relief tea is a herbal tea, developed by Mr. Chou in South Korea. Relief tea consists of herbs that have gone through a fermentation process for 35 days. In this series there are 5 types (Light tea, Goodnight etc.) and the complement each other well. 1 teabag can be used 3 times (3 cups) or used for 1 liter of tea. The tea tastes very mild and is equally good cold or hot. 10 teabags in a bag. Net weight per teabag 1.2g Ingredienser: Lilla klokkeblomst (40 %), rød salvie rod (30 %), mandarinskal (20 %) og kinesisk kaprifolium (10 %).', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Herbal','Caffeine-Free']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Rooibos With Raspberries And Cranberries', 'rooibos-with-raspberries-and-cranberries', '', '', 'Rooibos is grown only in a small area in the Cederberg region in the Western Cape province of South Africa. Rooibos is an herbal tea that comes from the bush Aspalathus linoaris. Rooibos is a popular herbal tea, as the fine and rich taste appeals to many. Rooibos is a light and friendly herbal tea as it cannot become bitter . If you make a large pot and don''t empty the pot, you can put the rest in the fridge and enjoy it later as a cold tea. Nice fresh fruit taste. Ingredienser: Rooibos (aspalathus linoaris) 95 %, tranebæraroma, hindbærstykker.', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Sweet','Nutty']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Rooibos with Vanilla Pieces', 'rooibos-with-vanilla-pieces', '', '', 'Rooibos is grown only in a small area in the Cederberg region in the Western Cape province of South Africa. Rooibos is an herbal tea that comes from the bush Aspalathus linoaris. Rooibos is a popular herbal tea, as the fine and rich taste appeals to many. It has a sweet taste. Beautiful red liquid and sweet aroma. Ingredients: rooibos ( aspalathus linoaris ), vanilla pieces.', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Sweet','Nutty']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Samidori Matcha', 'samidori-matcha-25g-tin-ceremonial', '', '薗北', 'Silky and smooth, Samidori has a subtle sweetness with undertones of banana and rosemary. Its forest green colour is accompanied by a lovely avocado aroma. It is made by grinding Tencha leaves from the first harvest of the year and is perfect for enjoying a pure cup of Matcha. Obubu Tea Farms is a family-owned tea farm located in Wazuka, Kyoto Prefecture, Japan, renowned for its dedication to traditional, sustainable tea cultivation. The farm produces high-quality, organic Japanese teas, including sencha, matcha, and hojicha, with a strong emphasis on preserving the environment and maintaining a connection to local tea heritage. Obubu also offers immersive tea experiences, allowing visito...', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Agata no Mori', 'sencha-agata-no-mori', '', '県の森', 'This sencha has a light and delicious taste, with an underlying sweet flavor note. It is made from tea leaves from Minami Yamashiro, a village in southern Kyoto. The tea is named after the Agata Shinto temple, which is located in front of the Horii family''s tea shop. When brewing Sencha Agata no Mori, it is recommended to use water at lower temperatures (around 60 degrees Celsius) to highlight the subtle nuances of the taste. Founded in 1879, Horii Shichimeien continues to cultivate the renowned 600-year-old Okunoyama Tea Garden, the sole remaining tea garden of Kyoto’s historic “seven beautiful gardens”. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Dosenbo Ippin', 'sencha-dosenbo-ippin-sencha', '', '洞川仙品', 'This is a sencha called pure sencha, which is grown without covering the tea garden at all. It is finished only with tea leaves cultivated in Dosenbo, a famous production area for sencha, at an altitude of about 500m. It is characterized by the refreshing aroma that goes through the nose like sencha and the umami behind the astringency, and the aroma is the best. Especially recommended for those who are not good at umami. The recommended water temperature is 60 to 70 degrees. Founded in 1879, Horii Shichimeien continues to cultivate the renowned 600-year-old Okunoyama Tea Garden, the sole remaining tea garden of Kyoto’s historic “seven beautiful gardens”. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Instant Sencha', 'sencha-instant-40-grams', '', 'インスタント煎茶', 'Instant sencha is a newer product from tea producer Hoshino Seichaen. It consists of freeze-dried Sencha tea that can simply be stirred into cold or warm water, providing an instant cup of quality green tea for the salaryman on the go. Ideal for the office, travels or a quick morning tea, Instant Sencha provides the wonderful flavour of Japanese Green tea with minimal fuss. Net weight: 40 grams Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Sencha Limited', 'sencha-limited', '', '限定煎茶', 'Sencha Limited is of very high quality. It is a level above Sencha Midori, with the natural juicy flavour of grass/vegetables. Sencha limited is harvested in limited quantities. Eat your tea: When you buy a fresh green tea like Sencha limited, you can end your tea break by eating the green leaves. Squeeze the leaves lightly so that the excess tea runs off. Add a few drops of mild soya if desired. Bright, clear, fresh flavour. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Meikun', 'sencha-meikun', '', '明君', 'This sencha is a blend of tea leaves that have been submitted to tea tasting competitions held annually in Japan and the Kansai region. It features a rich flavor and a refreshing aroma typical of sencha. The flavor, which you would never expect from sencha, fills your mouth and leaves a lingering aftertaste. It is recommended to brew the tea in water at about 50 degrees, with more tea leaves and less water. Gradually increase the temperature of the water for the second and third infusions, and finally pour it over with boiling water to enjoy a different flavor from the first infusion, allowing you to enjoy a variety of flavors with the same tea leaves. Founded in 1879, Horii Shichimeien c...', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Midori', 'sencha-midori', '', 'みどり', 'Grown in the misty mountains of Kyushu Island, Sencha Midori is a refined Japanese green tea from the renowned family-run garden Hoshino Seichaen. This spring-harvested tea is crafted exclusively from the Yabukita cultivar, prized for its balance and depth. The leaves are carefully steamed and dried through multiple stages, yielding a vibrant cup with a smooth, full-bodied character. Expect fresh notes of young grass, steamed greens, and a hint of asparagus, offering a true taste of early spring in Japan. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Midori Nibancha', 'sencha-midori-nibancha', '', 'みどり二番茶', 'This Sencha is grown by our long-time tea supplier, Hoshino Seichaen, located on Kyushu Island in southern Japan. The leaves are steamed and dried in several stages, which gives a soft and full-bodied tea with notes of grass and seaweed. Bright, clear, fresh flavour. Ingredienser: grøn te', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Sencha Shuppin', 'sencha-shuppin-2024-exhibition-tea', '', '煎茶秀品', 'This tea is from Yame in Japan and is produced by the family business Hoshino Seicha which has produced tea since 1946. Once a year, tea producers from all over Japan meet to exchange experiences and showcase their very best teas at Japan Exhibition where the teas are evaluated. Sencha Shuppin is an exhibition tea which means that it has been developed to show the best of Hoshino sei cha and is therefore of the absolute best quality. The tea here is a excellent example of that experience and unique production methods Hoshino Seicha possesses. The tea has a fine blue-green color in the cup, the texture is as soft as silk and the taste is elegant with notes of young green leaves, new vegeta...', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Sencha with Matcha', 'sencha-with-matcha', '', '抹茶入り煎茶', 'This blend brings together two standout Japanese teas for a fresh and flavorful experience. On one side, you’ve got the Tamakawa Sencha - a premium green tea from Shizuoka, Japan. It’s light, refreshing, and well-balanced, with a mix of natural sweetness, a touch of umami (savory flavor), and just enough astringency to keep it crisp. The tea has a soft and refreshing taste with a pleasant vegetable aroma Then comes Himawari Matcha , a high-quality culinary matcha. It’s smooth, rich, and slightly creamy, with that classic matcha kick. Blended together, this tea has a smooth texture, bold green color, and a layered flavor that starts fresh and ends with a mellow, satisfying finish. The senc...', '', 'green', 'true_tea', 'medium', 80, 2, 3, 'Sift 2g into a warmed bowl, add 70–80ml water at 80°C, whisk until frothy.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Pyogo-cha', 'shiitake-mushroom-tea', '', '표고차', 'Brew instructions: Tea: Use 2 grams for 300-400 ml of water. Use a filter if you want a clear tea. You can eat the mushroom pieces after brewing the tea. Rice: Add 1-2 spoons before cooking the rice. Also use the mushrooms in stews and soups. Ingredienser: shiitake svampe', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Herbal','Caffeine-Free']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE),
('Sing Luxus Breakfast tea', 'sing-luxus-breakfast-tea', '', '', 'Sing Luxus Breakfast tea consists of a delicate blend of Darjeeling 2nd flush and Ceylon tea as well as a touch of oil from the citrus fruit bergamot. Darjeling 2nd flush is characteristic with its delicious flavor and Ceylon adds a round flavor and dark color. The tea is also suitable with a little milk. A nice full-bodied tea that can be brewed into a strong tea without it becoming bitter. In summary a full-bodied and sweet aroma with a hint of smokiness. Ingredienser: sort te', '', 'blend', 'blend', 'medium', 95, 4, 3, 'Use 3g per 200ml at 95°C. Steep 3–4 minutes.', ARRAY['Aromatic']::text[], '{}'::text[], '#B07D56', 40, 30, 50, 40, 'default', 'Teapp', NULL, TRUE),
('Sing Winter Tea', 'sing-winter-tea', '', '', 'Lovely spiced tea, based on a black tea, with dried orange peels, cloves, ginger, pepper, apple pieces, raisins and cardamom. A savoury and rich afternoon tea that warms you up. The aroma and flavour of the spices is relaxing and satisfies the sweet tooth. A spicy tea that can be enjoyed with milk.', '', 'blend', 'blend', 'medium', 95, 4, 3, 'Use 3g per 200ml at 95°C. Steep 3–4 minutes.', ARRAY['Aromatic']::text[], '{}'::text[], '#B07D56', 40, 30, 50, 40, 'default', 'Teapp', NULL, TRUE),
('Sweet Bombay', 'sweet-bombay', '', '', 'A rich and aromatic black tea infused with the deep, floral notes of jasmine and the bright, zesty character of bergamot. The floral sweetness of jasmine intertwines with the citrusy sharpness of bergamot—famous from classic Earl Grey—creating a balanced and dreamlike infusion that stirs the senses. Ingredienser: sort te, grøn jasminte, bergamot, bourbonvanilje.', '', 'blend', 'blend', 'medium', 95, 4, 3, 'Use 3g per 200ml at 95°C. Steep 3–4 minutes.', ARRAY['Aromatic']::text[], '{}'::text[], '#B07D56', 40, 30, 50, 40, 'default', 'Teapp', NULL, TRUE),
('Chama Gudao Shou 2006', 'tea-horse-road-shu-puer-2006', '', '茶马古道熟茶', 'Special edition cake, with the stamps of all the towns that were originally a stop of the ancient tea-horse road. This cake celebrates the essence of pu’er shupu in either it most famous terroir, and the proficient processing technique. It gathers a blend of the most important Xishuangbanna mountains post-fermented in the heart of Menghai and packed in a special wrapping paper stamped by all the original stops of the ancient tea horse road. It is a celebration of the route that made Pu’er tea became widespread and well known in many countries, receiving the appreciation and esteem of many tea enthusiasts. The richness of color and the full, earthy aroma of its liquor is unique among many ...', '', 'shou_puerh', 'true_tea', 'medium', 100, 4, 3, 'Rinse once with boiling water. Then 30–60 seconds per infusion; 6+ infusions.', ARRAY['Earthy','Smooth']::text[], '{}'::text[], '#6B4226', 100, 80, 88, 68, 'default', 'Teapp', NULL, TRUE),
('Tsugumi', 'tsugumi', '', 'つぐみ', 'Medium-heavy in body with a lingering presence, Tsugumi has notes of pecans and chamomile. With a pale orange hue, this roasted Kukicha releases an aroma of wood, peat moss and toast. Produced from the stems of spring harvest Tencha leaves, Tsugumi is roasted in order to bring out its unique flavours. Ingredienser: ristede grøn te', '', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 3g per 200ml at 70–80°C. Steep 1.5–2 minutes; re-steep up to 3 times, slightly cooler each round.', ARRAY['Grassy','Fresh']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Wakoucha Pine Needle -  Obubu, Black Tea', 'wakoucha-pine-needle-obubu-black-tea', '', '', 'This Japanese black tea (Wa-koucha) is a special needle-like Japanese black tea. It has a slightly spicy flavour and underlying notes of molasses. The tea has a beautiful copper color with a lingering aroma of a freshly cut watermelon. In production, it has been rolled like Sencha, resulting in unique needle-shaped tea leaves. Pine Needle Wakoucha is a rare and wonderful tea, from Obubu Tea Farms in Kyoto. Ingredienser: sort te Net weight: 50 grams.', '', 'black', 'true_tea', 'medium', 95, 3, 3, 'Use 3g per 200ml at 90–95°C. Steep 3–4 minutes.', ARRAY['Bold','Malty']::text[], '{}'::text[], '#8B4513', 90, 70, 78, 55, 'default', 'Teapp', NULL, TRUE),
('White And Green Tea With Grapefruit & Flowers', 'white-and-green-tea-with-grapefruit-flowers', '', '', 'A delicate and aromatic blend of two exceptional teas: the fresh, grassy notes of green Sencha and the soft, silky character of the large-leaf white tea, White Downy. Infused with the brightness of grapefruit, the warmth of ginger, and a hint of smooth vanilla and cinnamon, this tea is gently rounded out with fragrant flower petals. Its subtle complexity makes it a perfect companion to afternoon cakes, pastries, or a quiet moment of indulgence. Ingredienser: grøn te (sencha), hvid te (white downy), krydderier (ingefær, kassia-kanel, kardemomme, nelliker, peber), tørret grapeskal, solsikke, saflor, naturlig vaniljearoma.', '', 'blend', 'blend', 'medium', 95, 4, 3, 'Use 3g per 200ml at 95°C. Steep 3–4 minutes.', ARRAY['Aromatic','Citrusy']::text[], '{}'::text[], '#B07D56', 40, 30, 50, 40, 'default', 'Teapp', NULL, TRUE),
('Shiro Houji', 'white-leaf-hojicha', '', '白焙じ', 'A tea consisting predominantly of stems from the rare white leaf tea which are then lightly roasted (Shiro Houji). It has a full mouthfeel, the rich umami is still present with an added layer of nuttiness similar to marron glacé. Ingredienser: ristede grøn te', '', 'green', 'true_tea', 'medium', 95, 2, 3, 'Use 3g per 200ml at 95°C. Steep 2 minutes; hojicha is low in astringency and forgiving.', ARRAY['Roasty','Smooth']::text[], '{}'::text[], '#7BA05B', 0, 10, 25, 15, 'default', 'Teapp', NULL, TRUE),
('Nannuo Dianhong', 'wild-forest-nannuo-dianhong', '', '南糯滇红', 'It is rare for a red tea to have such an intense fragrance, bringing the typical under-forest scents of bark and camphor that Nannuo Mountain is famous for. The infusion is bright red with shades of gold, and releases an intensely sweet flavor of honey and ripe peaches, complex yet gentle. This tea is called Dianhong, which means "Yunnan Red", and it is a very typical red tea from Yunnan. It is naturally oxidized in bamboo chests, and dried under the sunlight : this process assures the most complex evolution of flavours over the years, making this tea perfectly suitable for aging. Farmed, harvested, processed and distributed by Eastern Leaves Plantation Altitude: 1800 meters Origin: Bama ...', '', 'black', 'true_tea', 'medium', 95, 3, 3, 'Use 3g per 200ml at 90–95°C. Steep 3–4 minutes.', ARRAY['Bold','Malty']::text[], '{}'::text[], '#8B4513', 90, 70, 78, 55, 'default', 'Teapp', NULL, TRUE),
('Sucho-cha', 'willowy-tea-fermented-herbs', '', '수초차', 'Willowy tea is an herbal tea developed by Mr Chou in South Korea. Willowy tea consists of herbs that have undergone a 35-day fermentation process. There are 5 types in this range (Relief tea, Goodnight and others) and they complement each other well. 1 teabag can be used 3 times (3 cups) or used for 1 litre of tea. The tea tastes mild but deep and is equally good cold or hot. 10 teabags in a bag. Net weight per teabag 1.2g Ingredienser: Sasa bambus (40%), hvid brombærblad (30%), lotusblade (20%), mandarinskal (10%)', '', 'tisane', 'tisane', 'none', 100, 5, 3, 'Use 3g per 200ml of boiling water. Steep 5 minutes.', ARRAY['Herbal','Caffeine-Free']::text[], '{}'::text[], '#C0856A', 40, 30, 30, 20, 'default', 'Teapp', NULL, TRUE);